WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.Score, p.CreationDate, p.AnswerCount, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS PostRank FROM Posts AS p WHERE p.PostTypeId = 1 AND p.Score > 0), UserBadges AS (SELECT u.Id AS UserId, COUNT(b.Id) AS BadgeCount, MAX(b.Class) AS HighestBadgeClass FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id), PostCloseReasons AS (SELECT ph.PostId, GROUP_CONCAT(cr.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON cr.Id = CAST(ph.Comment AS Nullable(Int16)) WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId) SELECT up.Id AS UserId, up.DisplayName, up.Reputation, rb.PostId, rb.Title, rb.Score, rb.CreationDate, rb.AnswerCount, cb.BadgeCount, cb.HighestBadgeClass, pcr.CloseReasons FROM Users AS up LEFT JOIN RankedPosts AS rb ON up.Id = rb.PostId LEFT JOIN UserBadges AS cb ON up.Id = cb.UserId LEFT JOIN PostCloseReasons AS pcr ON rb.PostId = pcr.PostId WHERE up.Reputation > 1000 AND (NOT (pcr.CloseReasons IS NULL) OR cb.BadgeCount > 0) ORDER BY up.Reputation DESC NULLS FIRST, rb.Score DESC NULLS FIRST